import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkOnly } from 'workbox-strategies';
import { BackgroundSyncPlugin } from 'workbox-background-sync';

declare let self: ServiceWorkerGlobalScope;

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// Background sync for snag reports
const bgSyncPlugin = new BackgroundSyncPlugin('snag-reports-queue', {
  maxRetentionTime: 24 * 60 // Retry for max 24 Hours (specified in minutes)
});

// Intercept snag report submissions (assuming a POST to /api/snags)
registerRoute(
  /\/api\/snags/,
  new NetworkOnly({
    plugins: [bgSyncPlugin],
  }),
  'POST'
);

// Listen for messages from the client
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Custom sync logic if needed beyond standard Workbox Background Sync
self.addEventListener('sync', (event: any) => {
  if (event.tag === 'snag-sync') {
    console.log('Background sync triggered for snag-sync');
    // Here you would typically fetch queued reports from IndexedDB and send them
  }
});
